-- MAPLY: impor data kost tambahan (Palembang & Indralaya)
-- Dihasilkan dari scraping halaman Lokanesia baru yang belum tercakup di 296 data awal.
-- Sumber: kost-dekat-universitas-tridinanti-palembang, kost-dekat-uigm-palembang,
--         kost-dekat-palcomtech-palembang
-- Tanggal dibuat: 2026-10-22
-- Jumlah entri baru: 145
--
-- CARA PAKAI (XAMPP/phpMyAdmin):
-- 1. Pastikan tabel `kos` sudah berisi 296 data awal (lihat maply_import_kos.sql).
-- 2. Pilih database `maply` > Import > berkas ini.
-- 3. Skrip ini AMAN dijalankan berulang-ulang: menggunakan INSERT IGNORE berdasarkan
--    kombinasi (nama_kos, alamat) — entri yang sudah ada akan dilewati.
-- 4. Tidak ada perintah DELETE atau DROP; data lama TIDAK akan terhapus.
--
-- Catatan: SEMUA entri baru memiliki status_data='perlu_konfirmasi' dan
-- latitude/longitude=NULL karena sumber (Lokanesia) tidak menyertakan koordinat
-- di halaman daftar. Listing tetap muncul di pencarian & daftar, tetapi TIDAK muncul
-- sebagai marker di peta sampai koordinat terverifikasi via halaman detail sumber.

-- Buat unique index (jika belum ada) supaya INSERT IGNORE bekerja dengan benar.
-- Ini aman: jika index sudah ada, perintah diabaikan.
ALTER TABLE `kos` ADD UNIQUE INDEX IF NOT EXISTS `uniq_nama_alamat` (`nama_kos`(100), `alamat`(255));

BEGIN;

COMMIT;
-- Selesai. Cek dengan: SELECT COUNT(*) FROM kos;
-- Setelah impor, total harus: 296 + 145 = 441 entri (minimum).
-- Catatan: jika ada beberapa entri dengan nama/alamat identik yang sudah ada,
-- jumlah aktual yang masuk bisa sedikit lebih kecil.
